WIDTH=518
def para(text,style='BodyGuide'):return Paragraph(html.escape(text),STYLE[style])
def flow(labels,branches=None):
    gap=48 if branches else 38
    height=len(labels)*gap+12;d=Drawing(WIDTH,height)
    x,w,mid=(12,310,167) if branches else (73,372,259)
    for i,label in enumerate(labels):
        y=height-gap*(i+1)
        if branches and i<2:
            d.add(Polygon([x,y+18,mid,y+38,x+w,y+18,mid,y-2],fillColor=colors.HexColor('#edf4ef'),strokeColor=colors.HexColor('#507362')))
        else:d.add(Rect(x,y,w,36 if branches else 28,rx=5,ry=5,fillColor=colors.HexColor('#edf4ef'),strokeColor=colors.HexColor('#507362')))
        lines=textwrap.wrap(label,46 if branches else 55)
        for j,line in enumerate(lines):d.add(String(mid,y+(14 if branches else 11)-(j*11)+(len(lines)-1)*5,line,fontName='Helvetica',fontSize=9.5,textAnchor='middle',fillColor=colors.HexColor('#172a22')))
        if i<len(labels)-1:
            next_top=y-gap+(36 if branches else 28)
            d.add(Line(mid,y-2,mid,next_top,strokeColor=colors.HexColor('#507362')))
            d.add(Polygon([mid-3,next_top+3,mid+3,next_top+3,mid,next_top-1],fillColor=colors.HexColor('#507362'),strokeColor=None))
            if branches and i<2:d.add(String(mid+8,y-10,'Yes',fontName='Helvetica',fontSize=8,fillColor=colors.HexColor('#507362')))
        if branches and i<2:
            d.add(Rect(352,y-2,162,40,rx=4,ry=4,fillColor=colors.HexColor('#fff3de'),strokeColor=colors.HexColor('#ae824b')))
            d.add(Line(322,y+18,352,y+18,strokeColor=colors.HexColor('#ae824b')))
            d.add(String(330,y+25,'No',fontName='Helvetica',fontSize=8,fillColor=colors.HexColor('#735322')))
            for j,line in enumerate(textwrap.wrap(branches[i].split(': ',1)[-1],26)):
                d.add(String(433,y+22-j*11,line,fontName='Helvetica',fontSize=9,textAnchor='middle',fillColor=colors.HexColor('#735322')))
    return d
def pdftable(heads,rows,widths):
    cells=[[para(v,'CellHeaderGuide') for v in heads]]+[[para(str(v),'CellGuide') for v in row] for row in rows]
    widths=widths or [WIDTH/len(heads)]*len(heads)
    t=Table(cells,colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#274f3b')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f0f3f0')]),('LINEBELOW',(0,0),(-1,0),.5,colors.HexColor('#274f3b'))]))
    return t
STORY=[];HTML=[];DIAGRAMS={}
def emit(blocks):
    for block in blocks:
        kind=block[0]
        if kind=='p':STORY.append(para(block[1]));HTML.append('<p>'+html.escape(block[1])+'</p>')
        elif kind=='h':STORY.append(para(block[1],'GuideH2'));HTML.append('<h3>'+html.escape(block[1])+'</h3>')
        elif kind=='steps':
            HTML.append('<ol>')
            for i,text in enumerate(block[1],1):STORY.append(para(f'{i}. {text}'));HTML.append('<li>'+html.escape(text)+'</li>')
            HTML.append('</ol>')
        elif kind=='table':
            STORY.extend([pdftable(block[1],block[2],block[3]),Spacer(1,10)])
            HTML.append('<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+html.escape(x)+'</th>' for x in block[1])+'</tr></thead><tbody>')
            for row in block[2]:HTML.append('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>')
            HTML.append('</tbody></table></div>')
        elif kind=='diagram':
            _,key,title,labels,branches=block;d=flow(labels,branches);STORY.extend([para(title,'GuideH2'),d,Spacer(1,10)])
            svg=renderSVG.drawToString(d);DIAGRAMS[key]=svg
            HTML.append('<figure><img alt="'+html.escape(title+'; '+' then '.join(labels),quote=True)+'" src="data:image/svg+xml;base64,'+base64.b64encode(svg.encode()).decode()+'"><figcaption>'+html.escape(title)+'</figcaption></figure>')
        elif kind=='building':
            HTML.append('<article id="building-'+block[1]+'" data-building="'+block[1]+'">');begin=len(STORY);emit(block[2]);group=STORY[begin:];STORY[begin:]=[KeepTogether(group)];HTML.append('</article>')

