    STORY.append(Paragraph(f'<a name="{s["id"]}"/>{i}  {html.escape(s["title"])}',STYLE['GuideH1']));HTML.append('<section id="'+s['id']+'"><h2>'+html.escape(f"{i}  {s['title']}")+'</h2>');emit(s['blocks']);HTML.append('</section>')

